const listMapClusters = `-- name: ListMapClusters :many
SELECT count(*)::bigint AS count,
       avg(p.latitude)::double precision AS latitude,
       avg(p.longitude)::double precision AS longitude,
       min(p.latitude)::double precision AS south,
       min(p.longitude)::double precision AS west,
       max(p.latitude)::double precision AS north,
       max(p.longitude)::double precision AS east,
       (array_agg(p.id ORDER BY p.sort_at DESC, p.id DESC))[1]::bigint AS cover_id,
       (array_agg(p.preview_version ORDER BY p.sort_at DESC, p.id DESC))[1]::integer AS cover_version
FROM photos p
WHERE (p.owner_id = $1
       OR (photo_shared_directly(p, $1::bigint) OR photo_in_visible_album(p, $1::bigint)))
  AND p.status = 'ready'
  AND p.deleted_at IS NULL
  AND p.latitude IS NOT NULL
  AND NOT EXISTS (SELECT 1 FROM photo_links l WHERE l.hidden_id = p.id)
  AND NOT EXISTS (SELECT 1 FROM photo_archive a WHERE a.photo_id = p.id AND a.user_id = $1)
  AND p.latitude BETWEEN $2::double precision AND $3::double precision
  AND (CASE WHEN $4::double precision <= $5::double precision
            THEN p.longitude BETWEEN $4::double precision AND $5::double precision
            ELSE p.longitude >= $4::double precision OR p.longitude <= $5::double precision END)
GROUP BY floor((p.longitude + 180) / 360 * $6::double precision),
         floor((1 - ln(tan(radians(least(greatest(p.latitude, -85.05), 85.05)))
                        + 1 / cos(radians(least(greatest(p.latitude, -85.05), 85.05))))
                    / pi()) / 2 * $6::double precision)
ORDER BY count DESC
`

