const listTimeline = `-- name: ListTimeline :many
SELECT p.id, p.owner_id, p.sha256, p.mime, p.size, p.width, p.height, p.taken_at, p.exif, p.status, p.error, p.visibility, p.created_at, p.deleted_at, p.original_name, p.preview_format, p.sort_at, p.updated_at, p.purged_at, p.camera, p.lens, p.preview_version, p.duration, p.has_motion, p.content_identifier, p.video_copy, p.imported_latitude, p.imported_longitude, p.description, p.hdr, p.has_raw, p.latitude, p.longitude, p.source_path, p.phash, p.rotation, p.preview_rotation
FROM photos p
WHERE (p.owner_id = $1
       OR ($2::boolean AND p.status = 'ready'
           AND (photo_shared_directly(p, $1::bigint) OR photo_in_visible_album(p, $1::bigint))))
  AND p.deleted_at IS NULL
  -- A photo not processed yet has no date or size to place it by.
  AND p.status <> 'pending'
  AND NOT EXISTS (SELECT 1 FROM photo_links l WHERE l.hidden_id = p.id)
  AND (NOT $3::boolean
       OR EXISTS (SELECT 1 FROM photo_favorites f WHERE f.photo_id = p.id AND f.user_id = $1))
  -- The user's archived photos leave the timeline and stay in albums and
  -- favorites; the archived filter lists only them.
  AND (CASE WHEN $4::boolean
            THEN EXISTS (SELECT 1 FROM photo_archive a WHERE a.photo_id = p.id AND a.user_id = $1)
            WHEN $5::bigint IS NULL AND NOT $3::boolean
            THEN NOT EXISTS (SELECT 1 FROM photo_archive a WHERE a.photo_id = p.id AND a.user_id = $1)
            ELSE true END)
  AND ($6::timestamptz IS NULL
       OR (p.sort_at, p.id) < ($6::timestamptz, $7::bigint))
  AND ($8::timestamptz IS NULL OR p.sort_at >= $8::timestamptz)
  AND ($9::timestamptz IS NULL OR p.sort_at < $9::timestamptz)
  AND ($5::bigint IS NULL
       OR EXISTS (SELECT 1 FROM album_photos ap WHERE ap.photo_id = p.id AND ap.album_id = $5::bigint))
  AND ($10::bigint[] IS NULL
       OR (p.owner_id = $1
           AND EXISTS (SELECT 1 FROM photo_tags pt WHERE pt.photo_id = p.id AND pt.tag_id = ANY ($10::bigint[]))))
  AND ($11::text[] IS NULL OR p.camera = ANY ($11::text[]))
  AND ($12::text[] IS NULL OR p.lens = ANY ($12::text[]))
  AND ($13::text[] IS NULL OR photo_kinds(p.mime, p.has_motion, p.has_raw) && $13::text[])
  -- The photos taken inside a box of coordinates, which may cross the date
  -- line (west east of east). The API allows it only where it shows locations.
  AND ($14::double precision IS NULL
       OR (p.latitude BETWEEN $14::double precision AND $15::double precision
           AND (CASE WHEN $16::double precision <= $17::double precision
                     THEN p.longitude BETWEEN $16::double precision AND $17::double precision
                     ELSE p.longitude >= $16::double precision OR p.longitude <= $17::double precision END)))
ORDER BY p.sort_at DESC, p.id DESC
LIMIT $18
`

